         }

         // Now, for the "1% of balance" requirement:
         // We need to determine a `volume` such that if the Stop Loss `stopLossPrice` is hit,
         // the loss will be `maxLossMoney`.
         // Loss calculation:
         // For BUY: Loss = (EntryPrice - StopLossPrice) * Volume * ContractSize (if applicable)
         // For SELL: Loss = (StopLossPrice - EntryPrice) * Volume * ContractSize (if applicable)
         // In MQL5, the `trade.Buy` and `trade.Sell` functions require you to specify Volume.
         // Therefore, we must FIRST calculate the correct `volume` based on the desired `maxLossMoney` and `stopLossPips`.

         // --- Calculate Volume based on 1% Balance Risk and SL Pips ---
         double lossPerPipPerLot = SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_VALUE) / SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_SIZE);
         // This `lossPerPipPerLot` is the value of 1 pip for 1 standard lot.
         // (e.g., for EURUSD, 1 pip is 0.0001. Tick Value for 1 lot (100k EUR) is $10.
         // So, 1 pip is $10 / 100000 units * 100000 units = $1.
         // For USDJPY, 1 pip is 0.01. Tick Value for 1 lot (100k USD) is $10.
         // So, 1 pip is $10 / 100 units * 100 units = $10.
         // The formula `SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_VALUE) / SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_SIZE)`
         // correctly gives the monetary value of 1 point for 1 lot.
         // To get the value of 1 pip for 1 lot: multiply by 10^(Digits - PointDigits) or similar.
         // A simpler way is to use the fact that `stopLossPips * pointValue` is the price difference.
         // The total monetary loss for a given volume is:
         // `abs(EntryPrice - StopLossPrice) * volume * MarketLotSize` (if not already factored)
         // The difference `abs(EntryPrice - StopLossPrice)` is `stopLossPips * pointValue`.
         // So, Monetary Loss = `stopLossPips * pointValue * volume * MarketLotSize`

         // Let's use `pointValue` and `stopLossPips` directly to get the monetary loss per lot.
         // Monetary Loss Per Lot = `stopLossPips * pointValue` (This is NOT correct. It's the price difference for 1 unit)
         // We need value per point and per lot.
         // Value per point for 1 lot = SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_VALUE) / SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_SIZE)
         // Value per pip for 1 lot = Value per point for 1 lot * (pointValue / TickSize) ^ -1 for price diff
         // Let's use a simpler way with `pointValue`.

         // Monetary loss for 'volume' lots with 'stopLossPips' distance:
         // For BUY: (ClosePrice - stopLossPrice) * volume * ContractSize (if not 1)
         // (stopLossPips * pointValue) * volume * ContractSize

         // We need to find `volume` such that:
         // (stopLossPips * pointValue) * volume * ContractSize = maxLossMoney

         // Let's use the Contract Size for the symbol.
         double contractSize = SymbolInfoDouble(_Symbol, SYMBOL_TRADE_CONTRACT_SIZE);
         if (contractSize == 0) contractSize = 1.0; // Default to 1 if not found (though it should be found)

         // Correct loss calculation:
         // Difference in price: `stopLossPips * pointValue`
         // Monetary loss for `volume` lots: `(stopLossPips * pointValue) * volume * contractSize`
         // We want this to equal `maxLossMoney`.
         // So, `volume = maxLossMoney / (stopLossPips * pointValue * contractSize)`

         // Ensure `stopLossPips * pointValue * contractSize` is not zero to avoid division by zero error.
         double denominator = stopLossPips * pointValue * contractSize;
         if (denominator > 0)
         {
            volume = maxLossMoney / denominator;

            // --- Adjust Volume to Lot Size Rules ---
            double minLot = SymbolInfoDouble(_Symbol, SYMBOL_VOLUME_MIN);
            double maxLot = SymbolInfoDouble(_Symbol, SYMBOL_VOLUME_MAX);
            double lotStep = SymbolInfoDouble(_Symbol, SYMBOL_VOLUME_STEP);

            // Round down to the nearest allowed lot step
            volume = MathFloor(volume / lotStep) * lotStep;

            // Ensure volume is within min/max limits
            if (volume < minLot) volume = minLot;
            if (volume > maxLot) volume = maxLot;

            // Small check to avoid opening trades with zero volume if Risk is too high for minimum lot
            if (volume < minLot)
            {
               PrintFormat("Calculated volume is below minimum lot size. Cannot open trade with current risk settings. Volume: %f, Min Lot: %f", volume, minLot);
               return; // Exit if volume is not valid
            }

            // Calculate the actual Stop Loss Price for the determined volume.
            // The initial `stopLossPrice` calculation was based on a hypothetical SL distance.
            // Now we calculate the precise SL price for the determined `volume` that results in `maxLossMoney`.
            // We know `maxLossMoney = (EntryPrice - SL_Price) * Volume * ContractSize` (for BUY)
            // `SL_Price = EntryPrice - (maxLossMoney / (Volume * ContractSize))`

            if (orderType == ORDER_TYPE_BUY)
            {
               stopLossPrice = ClosePrice - (maxLossMoney / (volume * contractSize));
            }
            else if (orderType == ORDER_TYPE_SELL)
            {
               stopLossPrice = ClosePrice + (maxLossMoney / (volume * contractSize));
            }

            // Re-round the stopLossPrice to the correct number of digits
            stopLossPrice = DoubleToString(stopLossPrice, digits);
            stopLossPrice = StringToDouble(stopLossPrice);


            // Place the BUY order
            PrintFormat("Opening BUY trade. Balance: %.2f, Risk: %.2f (%.2f%%), Volume: %.2f, Stop Loss Price: %.10f",
                         balance, maxLossMoney, PercentageOfBalance, volume, stopLossPrice);

            if (trade.Buy(volume, _Symbol, ClosePrice, stopLossPrice, takeProfitPrice, "Buy with Dynamic SL"))
            {
               Print("BUY order placed successfully.");
            }
            else
            {
               PrintFormat("Error placing BUY order: %s", trade.ResultComment());
            }
         }
         else
         {
            Print("Denominator for volume calculation is zero or negative. Cannot calculate volume.");
         }
      }
      else if (orderType == ORDER_TYPE_SELL)
      {
         // Similar logic for SELL orders. Let's reuse the BUY logic for demonstration.
         // You would need to define SL_PIPS_FOR_SELL and adjust prices.
         // For this simplified example, let's assume we only open BUY.
         // If you need SELL, implement the logic similar to the BUY block.
      }
      else
      {
         // Handle other order types if necessary
      }
   }

   // Example of modifying an open trade's Stop Loss to be 1% of balance.
   // This is less common as the 1% is usually applied at trade entry.
   // If you wanted to dynamically adjust SL for existing trades, you'd iterate through
   // your open positions, calculate the current balance, calculate the desired SL price/pips
   // for that specific position based on the 1%, and then modify the order.
   // Be cautious with modifying SL of existing trades, it can lead to unexpected results
   // if your balance fluctuates significantly.
}

//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
{
   //---
   Print("StopLossPercentage Expert deinitialized. Reason: ", reason);
   //---
}

//+------------------------------------------------------------------+
//| Helper function to calculate the monetary value of one pip       |
